it('a plain-digit "up to N" clause parses to the correct limit', () => {
  const digitSeven = makeCard({
    name: 'Seven Stars',
    oracle_text: 'A deck can have up to 7 cards named Seven Stars.',
  });
  assert.strictEqual(singletonLimit(digitSeven), 7);
  const digitTwelve = makeCard({
    name: 'Twelve Tokens',
    oracle_text: 'A deck can have up to 12 cards named Twelve Tokens.',
  });
  assert.strictEqual(singletonLimit(digitTwelve), 12);
  const digitOne = makeCard({
    name: 'One Coin',
    oracle_text: 'A deck can have up to 1 cards named One Coin.',
  });
  assert.strictEqual(singletonLimit(digitOne), 1);
});

it('a genuinely unparseable number still returns 1 AND triggers a warning', () => {
  const unparseable = makeCard({
    name: 'Unparseable Card',
    oracle_text: 'A deck can have up to thirteen cards named Unparseable Card.',
  });
  const originalWarn = console.warn;
  let warningCaptured = false;
  console.warn = () => { warningCaptured = true; };
  const result = singletonLimit(unparseable);
  console.warn = originalWarn;
  assert.strictEqual(result, 1);
  assert.strictEqual(warningCaptured, true);
});
});

